/**
 * R59 analytics tests. ALL fixtures below are SYNTHETIC (generated by a seeded PRNG in this file);
 * they are not real players and not recorded data.
 */
import { describe, expect, it } from "vitest";
import { analyzePlayer, angleDelta, binomZ, killMetrics, populationBaseline, DEFAULT_BASELINE, MIN_KILLS, type KillRec, type TraceSample } from "./ac-analytics";

function rng(seed: number) { return () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 2 ** 32; }; }

/** SYNTHETIC human-like engagement: aim starts 15-40° off, converges over 180-450 ms with a smooth curve, some overshoot. */
function humanTrace(r: () => number): TraceSample[] {
  const start = 15 + r() * 25, reach = 180 + r() * 270, yaw0 = r() * 360, out: TraceSample[] = [];
  for (let dt = -750; dt <= 0; dt += 31) {
    const p = Math.min(1, Math.max(0, (dt + reach) / reach));
    const ease = 1 - (1 - p) ** 2;
    const err = Math.max(0.3 + r() * 2.5, start * (1 - ease) + (r() - 0.5) * 1.5);
    out.push({ dt, pitch: 2 + (r() - 0.5) * 2, yaw: yaw0 + (start - err), err: Math.abs(err) });
  }
  return out;
}
/** SYNTHETIC "aim-lock" pattern: aim far off, then one ~35 ms jump onto the target with no correction. */
function lockTrace(r: () => number): TraceSample[] {
  const start = 55 + r() * 40, yaw0 = r() * 360, snapAt = -(40 + Math.floor(r() * 25)), out: TraceSample[] = [];
  for (let dt = -750; dt <= 0; dt += 31) {
    const on = dt >= snapAt;
    out.push({ dt, pitch: 1, yaw: on ? yaw0 + start : yaw0 + r() * 0.5, err: on ? 0.2 + r() * 0.1 : start });
  }
  return out;
}
const RIFLES = ["ak47", "m4a1_silencer", "m4a1", "galilar", "famas", "deagle", "usp_silencer", "glock"];
function human(seed: number, n: number, o: { hs?: number; wb?: number; smoke?: number; weapons?: string[] } = {}): KillRec[] {
  const r = rng(seed), w = o.weapons ?? RIFLES;
  return Array.from({ length: n }, () => ({ weapon: w[Math.floor(r() * w.length)], headshot: r() < (o.hs ?? 0.42), distance: 300 + r() * 1500, wallbang: r() < (o.wb ?? 0.03), throughSmoke: r() < (o.smoke ?? 0.02), attackerBlind: r() < 0.01, trace: humanTrace(r) }));
}
function locker(seed: number, n: number): KillRec[] {
  const r = rng(seed);
  return Array.from({ length: n }, () => ({ weapon: RIFLES[Math.floor(r() * 4)], headshot: r() < 0.85, distance: 300 + r() * 1500, wallbang: r() < 0.2, throughSmoke: r() < 0.12, attackerBlind: false, trace: lockTrace(r) }));
}

describe("ac-analytics primitives", () => {
  it("wraps yaw deltas", () => { expect(angleDelta(179, -179)).toBeCloseTo(2); expect(angleDelta(-170, 170)).toBeCloseTo(-20); });
  it("binomial z is ~0 at the expected rate and large far above it", () => { expect(Math.abs(binomZ(45, 100, 0.45))).toBeLessThan(0.01); expect(binomZ(90, 100, 0.45)).toBeGreaterThan(8); });
  it("measures snap speed and reaction on a SYNTHETIC lock trace", () => {
    const k = killMetrics({ weapon: "ak47", headshot: true, distance: 900, wallbang: false, throughSmoke: false, attackerBlind: false, trace: lockTrace(rng(1)) });
    expect(k.peakSnap).toBeGreaterThan(900);
    expect(k.flickLock).toBe(true);
    expect(k.reactionMs).toBeLessThan(120);
  });
  it("does not call a SYNTHETIC smooth human acquisition a flick-lock", () => {
    const r = rng(2);
    const locks = Array.from({ length: 200 }, () => killMetrics({ weapon: "ak47", headshot: false, distance: 900, wallbang: false, throughSmoke: false, attackerBlind: false, trace: humanTrace(r) })).filter((x) => x.flickLock).length;
    expect(locks).toBeLessThan(10);
  });
  it("handles empty / short traces", () => { expect(killMetrics({ weapon: "ak47", headshot: false, distance: 1, wallbang: false, throughSmoke: false, attackerBlind: false, trace: [] }).reactionMs).toBeNull(); });
});

describe("analyzePlayer on SYNTHETIC fixtures", () => {
  it("flags the SYNTHETIC aim-lock profile high with explanations", () => {
    const a = analyzePlayer(locker(7, 24));
    expect(a.level).toBe("high");
    expect(a.reviewable).toBe(true);
    const keys = a.reasons.map((x) => x.key);
    expect(keys).toEqual(expect.arrayContaining(["hs_rate", "flick_lock", "fast_reaction"]));
    for (const x of a.reasons) expect(x.text.length).toBeGreaterThan(10);
  });
  it("false-positive check: 200 SYNTHETIC average human matches never reach review", () => {
    for (let i = 0; i < 200; i++) expect(analyzePlayer(human(1000 + i, 12 + (i % 20))).reviewable).toBe(false);
  });
  it("false-positive check: SYNTHETIC hot headshot game alone stays below review (single indicator cap)", () => {
    const a = analyzePlayer(human(55, 30, { hs: 0.9 }));
    expect(a.reasons.map((r) => r.key)).toContain("hs_rate");
    expect(a.reviewable).toBe(false);
  });
  it("false-positive check: SYNTHETIC smoke/wall spammer alone stays below review", () => {
    expect(analyzePlayer(human(56, 20, { smoke: 0.25 })).reviewable).toBe(false);
    expect(analyzePlayer(human(57, 20, { wb: 0.25 })).reviewable).toBe(false);
  });
  it("false-positive check: SYNTHETIC AWP player flicks are not scored as aim-lock", () => {
    const r = rng(9);
    const kills = Array.from({ length: 25 }, () => ({ weapon: "awp", headshot: r() < 0.3, distance: 1500, wallbang: false, throughSmoke: false, attackerBlind: false, trace: lockTrace(r) }));
    expect(analyzePlayer(kills).score).toBe(0);
  });
  it("needs a minimum number of kills", () => {
    expect(analyzePlayer(locker(3, MIN_KILLS - 1)).score).toBe(0);
  });
  it("ignores knife and grenade kills for aim metrics", () => {
    const a = analyzePlayer(Array.from({ length: 10 }, () => ({ weapon: "hegrenade", headshot: false, distance: 300, wallbang: true, throughSmoke: false, attackerBlind: false, trace: lockTrace(rng(4)) })));
    expect(a.aimKills).toBe(0);
    expect(a.reasons.find((r) => r.key === "flick_lock")).toBeUndefined();
  });
  it("population baseline falls back to defaults on a small sample and clamps on a large one", () => {
    expect(populationBaseline(human(1, 50))).toEqual(DEFAULT_BASELINE);
    const b = populationBaseline([...human(2, 600)]);
    expect(b.hsRate).toBeGreaterThan(0.3); expect(b.hsRate).toBeLessThan(0.55);
  });
});
